/**
 * Renders report diagrams (Mermaid code generated by the API) to SVG.
 *
 * Mermaid is large, so it is loaded only when a report actually contains a diagram. It runs with
 * securityLevel "strict" (no links, scripts or HTML in labels) and SVG text labels (not HTML), so a diagram
 * can also be drawn onto a canvas for Word export.
 */
type Mermaid = (typeof import("mermaid"))["default"];

let loader: Promise<Mermaid> | null = null;

export function loadMermaid(): Promise<Mermaid> {
  loader ??= import("mermaid").then(({ default: mermaid }) => {
    mermaid.initialize({
      startOnLoad: false,
      securityLevel: "strict",
      layout: "dagre", // the default layout; never Mermaid's much larger ELK engine
      theme: "base",
      fontFamily: '"Inter Variable", Inter, system-ui, sans-serif',
      themeVariables: {
        fontFamily: '"Inter Variable", Inter, system-ui, sans-serif',
        fontSize: "14px",
        background: "#ffffff",
        primaryColor: "#eef3ec",
        primaryBorderColor: "#3f5443",
        primaryTextColor: "#1c1d1a",
        secondaryColor: "#faf8f2",
        tertiaryColor: "#ffffff",
        lineColor: "#686a62",
        textColor: "#1c1d1a",
        edgeLabelBackground: "#ffffff",
        cScale0: "#eef3ec",
        cScale1: "#e6ece4",
        cScale2: "#faf8f2",
        cScale3: "#f3f0e2",
        cScaleLabel0: "#1c1d1a",
        cScaleLabel1: "#1c1d1a",
        cScaleLabel2: "#1c1d1a",
        cScaleLabel3: "#1c1d1a",
      },
      flowchart: { htmlLabels: false, curve: "basis", useMaxWidth: true, padding: 14, nodeSpacing: 36, rankSpacing: 40, wrappingWidth: 420 },
      timeline: { useMaxWidth: true, disableMulticolor: false },
    });
    return mermaid;
  });
  return loader;
}

let seq = 0;

/** SVG markup for a diagram; rejects if the code doesn't parse. */
export async function renderDiagram(code: string): Promise<string> {
  const mermaid = await loadMermaid();
  if (!(await mermaid.parse(code, { suppressErrors: true }))) throw new Error("This diagram couldn't be drawn.");
  const { svg } = await mermaid.render(`pramaan-diagram-${++seq}`, code);
  return svg;
}

/** A diagram as a PNG (for Word export): the SVG drawn on a white canvas at 2× for sharp printing. */
export async function diagramPng(code: string, maxWidth = 1200): Promise<{ data: Uint8Array; width: number; height: number }> {
  const svg = await renderDiagram(code);
  const doc = new DOMParser().parseFromString(svg, "image/svg+xml");
  const el = doc.documentElement;
  const box = (el.getAttribute("viewBox") ?? "").split(/\s+/).map(Number);
  const vw = box.length === 4 && box[2] > 0 ? box[2] : 800;
  const vh = box.length === 4 && box[3] > 0 ? box[3] : 400;
  const width = Math.min(maxWidth, Math.round(vw));
  const height = Math.round((vh / vw) * width);
  el.setAttribute("width", String(width));
  el.setAttribute("height", String(height));
  el.removeAttribute("style"); // max-width: 100% would collapse an unsized image
  const url = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(new XMLSerializer().serializeToString(el))}`;
  const img = await new Promise<HTMLImageElement>((resolve, reject) => {
    const i = new Image();
    i.onload = () => resolve(i);
    i.onerror = () => reject(new Error("diagram image failed"));
    i.src = url;
  });
  const canvas = document.createElement("canvas");
  canvas.width = width * 2;
  canvas.height = height * 2;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("canvas unavailable");
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
  const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/png"));
  if (!blob) throw new Error("diagram image failed");
  return { data: new Uint8Array(await blob.arrayBuffer()), width, height };
}
